// A Set node drops files, so take the upload straight from the form
const file = Object.values($('Upload a price list').first().binary)[0];
return [{ json: {}, binary: { data: file } }];

// One price list row -> one offer row. Column names come from settings.
const s = $('Ingest settings').first().json;
const c = s.columns; // {"source_sku":"Stock Code","brand":"Manufacturer","mpn":"Part No", ...}
const text = v => (v ?? '').toString().trim();
const num = v => {
  let t = text(v).replace(/[^0-9.,\-]/g, '');
  if (/,\d{1,2}$/.test(t)) t = t.replace(/\./g, '').replace(',', '.'); // "1.234,50" -> 1234.50
  else t = t.replace(/,/g, '');                                       // "1,234.50" -> 1234.50
  const n = parseFloat(t); return Number.isFinite(n) ? n : null;
};
const qty = v => { const n = parseInt(text(v).replace(/[^0-9]/g, ''), 10); return Number.isFinite(n) ? n : 0; }; // "20+" -> 20, "CALL" -> 0

return $input.all().map(({ json: r }) => {
  let cost = num(r[c.cost]);
  if (cost !== null && s.cost_includes_tax) cost = +(cost / (1 + s.tax_rate)).toFixed(2);
  return { json: {
    source: s.source_name, source_sku: text(r[c.source_sku]),
    mpn: text(r[c.mpn]), gtin: text(r[c.gtin]).replace(/\D/g, ''),
    brand: text(r[c.brand]), title: text(r[c.title]), description: text(r[c.description]).slice(0, 1500),
    category_raw: text(r[c.category]), cost, shipping_cost: s.shipping_per_unit || 0,
    rrp: num(r[c.rrp]), stock: qty(r[c.stock]), image_url: text(r[c.image]),
    ships_from: s.ships_from, raw: JSON.stringify(r).slice(0, 2000),
  } };
}).filter(i => i.json.source_sku && i.json.cost !== null);

// Parameters and string to sign for aliexpress.ds.product.get
const s = $('AliExpress settings').first().json;
const auth = $('Get token').first().json; // the one row in aliexpress_auth
const ids = [...new Set($input.all().map(i => String(i.json.item_id)))]; // one call per listing
return ids.map(item_id => {
  const params = {
    method: 'aliexpress.ds.product.get',
    app_key: auth.app_key,
    access_token: auth.access_token,
    timestamp: String(Date.now()),
    sign_method: 'sha256',
    product_id: item_id,
    ship_to_country: s.ship_to_country,
    target_currency: s.currency,
    target_language: 'en_US',
  };
  const toSign = Object.keys(params).sort().map(k => k + params[k]).join('');
  return { json: { item_id, params, toSign } };
});

const s = $('AliExpress settings').first().json;
const allowed = s.ships_from_allowed;
const wanted = $('Get AliExpress items').all().map(i => i.json); // a blank sku_id means every variant
const countryRx = /^(china( mainland)?|united (kingdom|states)|australia|spain|france|germany|poland|italy|czech republic|turkey|brazil|russian federation|saudi arabia)$/i;
const out = [];
for (const { json } of $input.all()) {
  const r = json.aliexpress_ds_product_get_response?.result;
  if (!r?.ae_item_base_info_dto) continue; // API error such as SHIP_TO_COUNTRY_PROHIBITED: the rows keep their last values
  const item = String(r.ae_item_base_info_dto.product_id);
  const skus = wanted.filter(w => String(w.item_id) === item).map(w => String(w.sku_id || ''));
  const brandProp = (r.ae_item_properties?.ae_item_property || []).find(p => /^brand/i.test(p.attr_name));
  const brand = /^(none|no brand|oem|other|unbranded)$/i.test(brandProp?.attr_value || 'none') ? '' : brandProp.attr_value;
  const images = (r.ae_multimedia_info_dto?.image_urls || '').split(';').filter(Boolean);
  for (const sku of r.ae_item_sku_info_dtos?.ae_item_sku_info_d_t_o || []) {
    const props = (sku.ae_sku_property_dtos?.ae_sku_property_d_t_o || []).map(p => p.property_value_definition_name || p.sku_property_value);
    const shipsFrom = props.find(p => countryRx.test(p)) || '';
    if (shipsFrom && !allowed.includes(shipsFrom.toLowerCase())) continue;
    if (Number(sku.sku_available_stock) <= 0) continue;
    if (!skus.includes('') && !skus.includes(String(sku.sku_id))) continue;
    const variant = props.filter(p => p !== shipsFrom).join(' / ');
    out.push({ json: {
      source: 'aliexpress', source_sku: `${item}-${sku.sku_id}`, item_id: item, sku_id: String(sku.sku_id),
      brand, gtin: (sku.ean_code || '').replace(/\D/g, ''), mpn: '',
      title: [r.ae_item_base_info_dto.subject, variant].filter(Boolean).join(' | '),
      category_raw: String(r.ae_item_base_info_dto.category_id),
      cost: Number(sku.offer_sale_price || sku.sku_price), stock: Number(sku.sku_available_stock),
      ships_from: shipsFrom || r.ae_store_info?.store_country_code || '',
      image_url: (sku.ae_sku_property_dtos?.ae_sku_property_d_t_o || []).find(p => p.sku_image)?.sku_image || images[0] || '',
      block_reason: sku.currency_code === s.currency ? '' : `priced in ${sku.currency_code}`,
    } });
  }
}
return out;

// Parameters and string to sign for aliexpress.ds.freight.query, one request per variant
const s = $('AliExpress settings').first().json;
const auth = $('Get token').first().json;
return $input.all().map(({ json: row }) => {
  const params = {
    method: 'aliexpress.ds.freight.query',
    app_key: auth.app_key,
    access_token: auth.access_token,
    timestamp: String(Date.now()),
    sign_method: 'sha256',
    queryDeliveryReq: JSON.stringify({ quantity: 1, shipToCountry: s.ship_to_country, productId: row.item_id,
      selectedSkuId: row.sku_id, language: 'en_US', locale: 'en_US', currency: s.currency }),
  };
  const toSign = Object.keys(params).sort().map(k => k + params[k]).join('');
  return { json: { ...row, params, toSign } };
});

// shipping_fee_cent is in currency units, not cents ("172.71" = US $172.71)
const s = $('AliExpress settings').first().json;
const sent = $('Sign freight request').all(0, $runIndex); // this run's requests, in the same order as the replies
return $input.all().map(({ json }, i) => {
  const { params, toSign, sign, retry_freight, ...offer } = sent[i].json;
  const res = json.aliexpress_ds_freight_query_response?.result;
  if (res?.msg === 'DELIVERY_RATE_LIMIT_FOR_SINGLE_PRODUCT' && $runIndex === 0) return { json: { ...offer, retry_freight: true } };
  if (String(res?.success) !== 'true') return { json: { ...offer, shipping_cost: null,
    block_reason: offer.block_reason || `no freight quote: ${res?.msg || json.error_response?.msg || 'request failed'}` } };
  const best = (res.delivery_options?.delivery_option_d_t_o || [])
    .filter(o => String(o.tracking) === 'true' && Number(o.max_delivery_days) <= s.max_delivery_days)
    .map(o => ({ ...o, fee: String(o.free_shipping) === 'true' ? 0 : Number(o.shipping_fee_cent) }))
    .sort((a, b) => a.fee - b.fee || a.max_delivery_days - b.max_delivery_days)[0];
  if (!best) return { json: { ...offer, shipping_cost: null, block_reason: offer.block_reason || `no tracked shipping within ${s.max_delivery_days} days` } };
  return { json: { ...offer, shipping_cost: best.fee, freight_method: best.company, delivery_days: Number(best.max_delivery_days) } };
});

// Token refresh is a system call: the API path goes in front of the string to sign
const a = $('Read token').first().json;
const params = { app_key: a.app_key, refresh_token: a.refresh_token, timestamp: String(Date.now()), sign_method: 'sha256' };
const toSign = '/auth/token/refresh' + Object.keys(params).sort().map(k => k + params[k]).join('');
// POST https://api-sg.aliexpress.com/rest/auth/token/refresh
return [{ json: { params, toSign } }];

// Title rules beat category rules. Nothing is dropped: every row leaves with a status.
const rules = $('Get category map').all().map(i => i.json).filter(r => r.pattern)
  .sort((a, b) => (a.match_field === 'title' ? 0 : 1) - (b.match_field === 'title' ? 0 : 1));
return $('Get new offers').all().map(({ json: o }) => {
  const rule = rules.find(r => r.source === o.source &&
    (r.match_field === 'title' ? new RegExp(r.pattern, 'i').test(o.title) : r.pattern === o.category_raw));
  if (o.block_reason) return { json: { ...o, status: 'blocked' } };
  if (!rule) return { json: { ...o, status: 'unmapped', block_reason: `no rule for "${o.category_raw}"` } };
  if (rule.action === 'block') return { json: { ...o, status: 'blocked', block_reason: rule.reason } };
  return { json: { ...o, status: 'candidate', product_type: rule.product_type, shopify_category_id: rule.shopify_category_id } };
});

