const s = $('Detect settings').first().json;
const taxFactor = s.prices_include_tax ? 1 + s.tax_rate : 1;
const out = [], byGtin = new Map();
$input.all().forEach((res, i) => {
  const o = { ...$('Candidates only').itemMatching(i).json, status: '' };
  const hit = res.json.data?.productVariants?.nodes?.[0];
  if (hit) return out.push({ ...o, status: 'on_store', product_id: hit.product.id });
  if (o.shipping_cost == null || o.shipping_cost === '') return out.push({ ...o, status: 'blocked', block_reason: o.block_reason || 'no shipping cost' });
  const landed = o.cost + o.shipping_cost;
  const floor = landed * (1 + s.min_margin) * taxFactor;
  let price = landed * s.markup * taxFactor;
  if (o.rrp && o.rrp >= floor) price = Math.min(price, o.rrp); // don't price above the brand's RRP
  o.est_price = Math.ceil(price - s.round_to) + s.round_to;    // 54.20 -> 54.95
  o.landed = landed;
  const prev = o.gtin && byGtin.get(o.gtin);                   // same barcode from two sources
  if (prev && prev.landed <= landed) return out.push({ ...o, status: 'duplicate' });
  if (prev) prev.status = 'duplicate';
  if (o.gtin) byGtin.set(o.gtin, o);
  out.push(o);
});
out.filter(o => !o.status).sort((a, b) => (b.stock > 0) - (a.stock > 0)).slice(0, s.batch_limit).forEach(o => {
  if (o.source === 'aliexpress' && s.aliexpress_pre_approved) o.status = 'approved';
  else { o.status = 'pending_review'; o.card_nonce = Math.random().toString(36).slice(2, 10); }
});
return out.map(json => ({ json }));

