const o = $('Get offer').first().json;
const out = String($json.text || '');
let title = (out.match(/^\s*title\s*:\s*(.+)$/im) || [])[1]?.trim() || '';
let desc = (out.match(/short description\s*:\s*([\s\S]+)/i) || [])[1]?.trim() || '';
const words = s => String(s).toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim().split(' ');
const source = new Set(words([o.title, o.brand, o.mpn, o.description].join(' ')));
// every token with a digit must exist in the source, whole: "SDCS/256GB" fails against "SDCS3/256GB"
const invented = title.split(/\s+/).filter(t => /\d/.test(t)).filter(t => !words(t).every(w => source.has(w)));
let reason = !title ? 'no title' : title.length > 80 ? 'too long' : invented.length ? 'not in source: ' + invented.join(', ') : null;
if (reason) title = [o.brand, o.title.split(' | ')[0]].filter(Boolean).join(' ').replace(/\s+/g, ' ').slice(0, 70);
if (desc.length < 40 || desc.length > 400 || /<[a-z]/i.test(desc)) desc = '';
return [{ json: { title, short_description: desc, title_source: reason ? 'fallback' : 'ai', title_reject_reason: reason } }];

const o = $('Get offer').first().json, c = $('Check copy').first().json, s = $('Draft settings').first().json;
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const variant = {
  optionValues: [{ optionName: 'Title', name: 'Default Title' }],
  sku: o.mpn || o.source_sku,
  price: o.est_price.toFixed(2),
  inventoryItem: { cost: (o.cost + (o.shipping_cost || 0)).toFixed(2), tracked: true },
  inventoryQuantities: [{ locationId: s.location_id, name: 'available', quantity: o.stock }],
};
if (o.gtin) variant.barcodes = [{ value: o.gtin }];
return [{ json: { input: {
  title: c.title,
  descriptionHtml: c.short_description ? `<p>${esc(c.short_description)}</p>` : '',
  vendor: o.brand || s.default_vendor,
  productType: o.product_type,
  ...(o.shopify_category_id ? { category: `gid://shopify/TaxonomyCategory/${o.shopify_category_id}` } : {}),
  status: 'DRAFT',
  tags: ['auto-import', `source-${o.source}`],
  productOptions: [{ name: 'Title', values: [{ name: 'Default Title' }] }],
  variants: [variant],
  files: o.image_url ? [{ originalSource: o.image_url, contentType: 'IMAGE', alt: c.title }] : [],
  metafields: [
    { namespace: 'sourcing', key: 'source', type: 'single_line_text_field', value: o.source },
    { namespace: 'sourcing', key: 'source_sku', type: 'single_line_text_field', value: o.source_sku },
  ],
} } }];

