// The second card: the AI copy over the supplier's title, a preview link and the go-live buttons
const o = $('Get offer').first().json, c = $('Check copy').first().json, s = $('Draft settings').first().json;
const v = $('Build product').first().json.input.variants[0];
const sent = $('Create draft').isExecuted ? $('Create draft').first().json : null;
const product = sent?.data?.productSet?.product;
const errors = [...(sent?.data?.productSet?.userErrors || []), ...(sent?.errors || [])].map(e => e.message).join('; ');
const nonce = Math.random().toString(36).slice(2, 10);
let status = o.status, note;
if (!sent) note = 'Dry run: nothing was created in Shopify. Set dry_run to false in the settings to create drafts.';
else if (product) { status = 'drafted'; note = 'Draft created. Check it in Shopify, then put it live here.'; }
else { status = 'draft_failed'; note = `Shopify refused the draft: ${errors || 'no product returned'}`; }
const main = { type: 'section', text: { type: 'mrkdwn', text: [
  `*${c.title}*`, c.short_description || '_No short description: the reply failed the check._', '',
  `Supplier title: ${o.title}`,
  `Price: ${v.price} ${s.currency} | Landed cost: ${v.inventoryItem.cost} | Copy: ${c.title_source}${c.title_reject_reason ? ` (${c.title_reject_reason})` : ''}`,
].join('\n').slice(0, 2900) } };
if (/^https:\/\//.test(o.image_url)) main.accessory = { type: 'image', image_url: o.image_url, alt_text: c.title.slice(0, 100) };
const blocks = [main, { type: 'context', elements: [{ type: 'mrkdwn', text: note.slice(0, 2900) }] }];
if (status === 'drafted') {
  const value = `${o.id}:${nonce}`;
  const buttons = [
    { type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Approve and go live' }, action_id: 'draft_golive', value },
    { type: 'button', style: 'danger', text: { type: 'plain_text', text: 'Reject' }, action_id: 'draft_reject', value },
  ];
  if (product.onlineStorePreviewUrl) buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Preview' }, url: product.onlineStorePreviewUrl, action_id: 'draft_preview' });
  buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Open in Shopify' }, url: `https://${s.store_domain}/admin/products/${product.legacyResourceId}`, action_id: 'draft_admin' });
  blocks.push({ type: 'actions', elements: buttons });
}
return [{ json: { row_id: o.id, status, product_id: product?.id || '', card_nonce: status === 'drafted' ? nonce : '',
  block_reason: status === 'draft_failed' ? errors.slice(0, 300) : (o.block_reason || ''), text: `Draft ready: ${c.title}`, blocks } }];

