parameters.jsCode:
const p = $json.data.product, s = $('Go live settings').first().json;
const v = p.variants.nodes[0] || {};
const price = Number(v.price), landed = Number(v.inventoryItem?.unitCost?.amount || 0);
const floor = landed * (s.prices_include_tax ? 1 + s.tax_rate : 1);
// mediaCount counts images Shopify failed to fetch, so check each image's status
const images = p.media.nodes.filter(m => m.mediaContentType === 'IMAGE');
const missing = [];
if (!images.some(m => m.status === 'READY')) missing.push(images.some(m => m.status === 'FAILED') ? 'a working image (Shopify could not fetch the supplier image)' : 'an image');
if (!p.productType) missing.push('a product type');
if (!p.category) missing.push('a category');
if (!(landed > 0 && price > floor)) missing.push(`a price above ${floor.toFixed(2)}`);
return [{ json: { id: p.id, ready: missing.length === 0, missing } }];

