={{ JSON.stringify({
  channel: $('When called by another lane').first().json.channel || $('Go live settings').first().json.slack_channel,
  thread_ts: $('When called by another lane').first().json.thread_ts || $('Get offer to publish').first().json.draft_card_ts,
  text: '' + (() => {
    const c = $('Check the draft').first().json;
    if (!c.ready) return ':warning: Not live yet. The draft still needs ' + c.missing.join(', ') + '. Fix it in Shopify, then tap Approve and go live again.';
    if (!$('Put it live').isExecuted) return 'Dry run: the draft passed every check. Set dry_run to false to put it live.';
    const r = $('Put it live').first().json;
    const errors = [ ...(r.errors || []), ...(r.data?.productUpdate?.userErrors || []), ...(r.data?.publishablePublish?.userErrors || []) ].map(e => e.message);
    if (errors.length) return ':x: Shopify refused: ' + errors.join('; ');
    const p = r.data.productUpdate.product;
    return ':white_check_mark: Live: ' + (p.onlineStoreUrl || p.handle);
  })()
}) }}
